class DataStore:
    def __init__(self, storage_path: str = "data"):
        self.storage_path = storage_path
        os.makedirs(storage_path, exist_ok=True)
        self.users_file = os.path.join(storage_path, "users.json")
        self.budgets_file = os.path.join(storage_path, "budgets.json")
        self._load_data()

    def _load_data(self):
        self.users: Dict[str, User] = {}
        self.budgets: Dict[str, Budget] = {}

        if os.path.exists(self.users_file):
            try:
                with open(self.users_file, 'r') as f:
                    user_data = json.load(f)
                    for uid, udata in user_data.items():
                        self.users[uid] = User.from_dict(udata)
            except (json.JSONDecodeError, KeyError):
                self.users = {}

        if os.path.exists(self.budgets_file):
            try:
                with open(self.budgets_file, 'r') as f:
                    budget_data = json.load(f)
                    for bid, bdata in budget_data.items():
                        self.budgets[bid] = Budget.from_dict(bdata)
            except (json.JSONDecodeError, KeyError):
                self.budgets = {}

    def _save_users(self):
        with open(self.users_file, 'w') as f:
            json.dump({uid: user.to_dict() for uid, user in self.users.items()}, f, indent=2)

    def _save_budgets(self):
        with open(self.budgets_file, 'w') as f:
            json.dump({bid: budget.to_dict() for bid, budget in self.budgets.items()}, f, indent=2)

    def save(self):
        self._save_users()
        self._save_budgets()

    def add_user(self, user: User) -> bool:
        if user.user_id in self.users:
            return False
        self.users[user.user_id] = user
        self.save()
        return True

    def get_user(self, user_id: str) -> Optional[User]:
        return self.users.get(user_id)

    def get_user_by_email(self, email: str) -> Optional[User]:
        for user in self.users.values():
            if user.email == email:
                return user
        return None

    def add_budget(self, budget: Budget) -> bool:
        if budget.budget_id in self.budgets:
            return False
        self.budgets[budget.budget_id] = budget
        self.save()
        return True

    def get_budget(self, budget_id: str) -> Optional[Budget]:
        return self.budgets.get(budget_id)

    def update_budget(self, budget: Budget) -> bool:
        if budget.budget_id not in self.budgets:
            return False
        self.budgets[budget.budget_id] = budget
        self.save()
        return True

    def delete_budget(self, budget_id: str) -> bool:
        if budget_id not in self.budgets:
            return False
        del self.budgets[budget_id]
        self.save()
        return True


