    def hash_password(self, password: str) -> str:
        return hashlib.sha256(password.encode()).hexdigest()

    def register_user(self, email: str, name: str, password: str) -> Tuple[bool, str]:
        if not email or not name or not password:
            return False, "All fields are required"
        if not re.match(r"^[^@]+@[^@]+\.[^@]+$", email):
            return False, "Invalid email format"
        if len(password) < 8:
            return False, "Password must be at least 8 characters"
        if any(u.email == email for u in self.users.values()):
            return False, "Email already registered"
        user_id = secrets.token_hex(8)
        user = User(
            user_id=user_id,
            email=email,
            name=name,
            password_hash=self.hash_password(password)
        )
        self.users[user_id] = user
        return True, user_id

    def login(self, email: str, password: str) -> Tuple[bool, Optional[str], str]:
        if not email or not password:
            return False, None, "Missing credentials"
        for user in self.users.values():
            if user.email == email and user.password_hash == self.hash_password(password):
                token = secrets.token_hex(16)
                self.sessions[token] = user.user_id
                return True, token, "Login successful"
        return False, None, "Invalid credentials"

    def logout(self, token: str) -> bool:
        if token in self.sessions:
            del self.sessions[token]
            return True
        return False

    def get_user_by_token(self, token: str) -> Optional[User]:
        user_id = self.sessions.get(token)
