            "members": {uid: perm.value for uid, perm in self.members.items()},
            "categories": {cid: cat.to_dict() for cid, cat in self.categories.items()},
            "transactions": [t.to_dict() for t in self.transactions],
            "goals": self.goals,
            "created_at": self.created_at,
            "updated_at": self.updated_at
        }

    def update_timestamp(self):
        self.updated_at = datetime.utcnow().isoformat()

    def add_member(self, user_id: str, permission: Permission):
        self.members[user_id] = permission
        self.update_timestamp()

    def remove_member(self, user_id: str):
        if user_id in self.members:
            del self.members[user_id]
            self.update_timestamp()

    def get_total_spent(self) -> float:
        return sum(
            t.amount for t in self.transactions
            if t.transaction_type == "expense"
        )

    def get_total_income(self) -> float:
        return sum(
            t.amount for t in self.transactions
            if t.transaction_type == "income"
        )

    def get_category_spending(self, category_id: str) -> float:
        return sum(
            t.amount for t in self.transactions
            if t.category_id == category_id and t.transaction_type == "expense"
        )

    def get_category_breakdown(self) -> Dict[str, float]:
        breakdown = {}
        for cat_id, cat in self.categories.items():
            spent = self.get_category_spending(cat_id)
            breakdown[cat_id] = spent
        return breakdown

    def get_progress_towards_goals(self) -> Dict[str, float]:
        progress = {}
        for goal_id, target in self.goals.items():
            spent = self.get_total_spent()
            progress[goal_id] = min(spent / target * 100, 100) if target > 0 else 0.0
        return progress

