    categories: Dict[str, BudgetCategory] = field(default_factory=dict)  # category_id -> BudgetCategory
    transactions: List[Transaction] = field(default_factory=list)
    goals: Dict[str, float] = field(default_factory=dict)  # goal_id -> target_amount
    created_at: str = field(default_factory=lambda: datetime.utcnow().isoformat())
    updated_at: str = field(default_factory=lambda: datetime.utcnow().isoformat())

    def to_dict(self) -> Dict:
        return {
            "budget_id": self.budget_id,
            "name": self.name,
            "description": self.description,
            "owner_id": self.owner_id,
            "members": {uid: perm.value for uid, perm in self.members.items()},
            "categories": {cid: cat.to_dict() for cid, cat in self.categories.items()},
            "transactions": [t.to_dict() for t in self.transactions],
            "goals": self.goals,
            "created_at": self.created_at,
            "updated_at": self.updated_at
        }

    @classmethod
    def from_dict(cls, data: Dict) -> 'Budget':
        members = {uid: Permission(perm) for uid, perm in data.get("members", {}).items()}
        categories = {cid: BudgetCategory.from_dict(cat_data) for cid, cat_data in data.get("categories", {}).items()}
        transactions = [Transaction.from_dict(t_data) for t_data in data.get("transactions", [])]
        return cls(
            budget_id=data["budget_id"],
            name=data["name"],
            description=data["description"],
            owner_id=data["owner_id"],
            members=members,
            categories=categories,
            transactions=transactions,
            goals=data.get("goals", {}),
            created_at=data.get("created_at", datetime.utcnow().isoformat()),
            updated_at=data.get("updated_at", datetime.utcnow().isoformat())
        )

    def update_timestamp(self):
        self.updated_at = datetime.utcnow().isoformat()

    def get_total_spent(self) -> float:
        return sum(
            t.amount for t in self.transactions
            if t.transaction_type == "expense"
        )

    def get_total_income(self) -> float:
        return sum(
            t.amount for t in self.transactions
            if t.transaction_type == "income"
        )

    def get_spending_by_category(self) -> Dict[str, float]:
        spending = {}
        for t in self.transactions:
            if t.transaction_type == "expense":
                spending[t.category] = spending.get(t.category, 0.0) + t.amount
        return spending

    def get_category_progress(self) -> Dict[str, Dict[str, Any]]:
        progress = {}
        for cat_id, cat in self.categories.items():
            spent = sum(
                t.amount for t in self.transactions
                if t.category == cat.name and t.transaction_type == "expense"
            )
            progress[cat.name] = {
                "spent": spent,
                "target": cat.target_amount,
                "remaining": cat.target_amount - spent,
                "percentage": (spent / cat.target_amount * 100) if cat.target_amount > 0 else 0
            }
        return progress

