class DataStore:
    def __init__(self, storage_path: str = "budgetsync_data.json"):
        self.storage_path = storage_path
        self._data = self._load()

    def _load(self) -> Dict[str, Any]:
        if os.path.exists(self.storage_path):
            try:
                with open(self.storage_path, 'r') as f:
                    return json.load(f)
            except (json.JSONDecodeError, IOError):
                return self._default_data()
        return self._default_data()

    def _default_data(self) -> Dict[str, Any]:
        return {
            "users": {},
            "budgets": {},
            "notifications": {},
            "feedbacks": []
        }

    def save(self):
        with open(self.storage_path, 'w') as f:
            json.dump(self._data, f, indent=2)

    # User operations
    def add_user(self, user: User):
        self._data["users"][user.user_id] = user.to_dict()
        self.save()

    def get_user(self, user_id: str) -> Optional[User]:
        data = self._data["users"].get(user_id)
        return User.from_dict(data) if data else None

    def get_user_by_email(self, email: str) -> Optional[User]:
        for user_data in self._data["users"].values():
            if user_data["email"] == email:
                return User.from_dict(user_data)
        return None

    def update_user(self, user: User):
        self._data["users"][user.user_id] = user.to_dict()
        self.save()

    # Budget operations
    def add_budget(self, budget: Budget):
        self._data["budgets"][budget.budget_id] = budget.to_dict()
        self.save()

    def get_budget(self, budget_id: str) -> Optional[Budget]:
        data = self._data["budgets"].get(budget_id)
        return Budget.from_dict(data) if data else None

    def update_budget(self, budget: Budget):
        budget.updated_at = datetime.utcnow().isoformat()
        self._data["budgets"][budget.budget_id] = budget.to_dict()
        self.save()

    def delete_budget(self, budget_id: str):
        if budget_id in self._data["budgets"]:
            del self._data["budgets"][budget_id]
            self.save()

    # Transaction operations
    def add_transaction(self, transaction: Transaction):
        self._data["budgets"][transaction.budget_id]["transactions"].append(
            transaction.to_dict()
        )
        self.save()

    def get_transactions_for_budget(self, budget_id: str) -> List[Transaction]:
        budget_data = self._data["budgets"].get(budget_id)
        if not budget_data:
            return []
        return [Transaction.from_dict(t) for t in budget_data.get("transactions", [])]

    # Notification operations
    def add_notification(self, notification: Notification):
        self._data["notifications"][notification.notification_id] = notification.to_dict()
        self.save()

    def get_notifications_for_user(self, user_id: str) -> List[Notification]:
        return [
            Notification.from_dict(n)
            for n in self._data["notifications"].values()
            if n["user_id"] == user_id
        ]

    def mark_notification_as_read(self, notification_id: str):
        if notification_id in self._data["notifications"]:
            self._data["notifications"][notification_id]["is_read"] = True
            self.save()

    # Feedback operations
    def add_feedback(self, feedback: Dict[str, Any]):
        self._data["feedbacks"].append(feedback)
        self.save()

    def get_all_feedback(self) -> List[Dict[str, Any]]:
